p='src/server/services/usage-service.ts'
s=open(p).read()
def rep(old,new):
    global s
    assert s.count(old)==1, (s.count(old), old[:70])
    s=s.replace(old,new)
rep('import type { Actor } from "@/types/member";','import { isBillableRole } from "@/types/member";\nimport type { Actor, Role } from "@/types/member";')
rep('''/** Fraction of a quota at which the "approaching limit" event fires. */
const WARN_THRESHOLD = 0.9;
''','''/** Fraction of a quota at which the "approaching limit" event fires. */
const WARN_THRESHOLD = 0.9;

/** A member holds one seat when their role is billable; a viewer holds none. */
function seatsHeldBy(role: Role): number {
  return isBillableRole(role) ? 1 : 0;
}
''')
rep('''    subscribe("member.joined", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
    }),
    subscribe("member.removed", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
    }),''','''    subscribe("member.joined", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, {
        seatsUsed: seatsHeldBy(payload.role),
      });
    }),
    subscribe("member.role_changed", async (payload) => {
      const delta = seatsHeldBy(payload.to) - seatsHeldBy(payload.from);
      if (delta === 0) return;
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: delta });
    }),
    subscribe("member.removed", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, {
        seatsUsed: -seatsHeldBy(payload.role),
      });
    }),''')
open(p,'w').write(s)

p='src/server/services/organization-service.ts'
s=open(p).read()
rep('''  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
  await usageRepo.recomputeUsage(org.id);

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });
''','''  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });

  // Recount after the join event: the join listener already adds the owner's
  // seat, and the recount must be the last write so the two cannot double up.
  await usageRepo.recomputeUsage(org.id);
''')
open(p,'w').write(s)
EOF
echo done

