/**
 * Seats in use: billable active members plus pending invitations for a billable
 * role. Role changes and invitations are both checked against this one number.
 */
export async function seatsInUse(orgId: OrgId): Promise<number> {
  return (
    (await memberRepo.countActiveMembers(orgId)) +
    (await invitationRepo.countPendingInvitations(orgId))
  );
}

/**
 * Throws when taking `requested` more seats would exceed the plan. Asking for
 * no seats never fails, even on a plan that is already over its quota.
 */
export async function assertSeatsAvailable(
  orgId: OrgId,
  requested: number,
): Promise<void> {
  if (requested === 0) return;

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  const seatsUsed = await seatsInUse(orgId);

  if (wouldExceedLimit(org.plan, "seats", seatsUsed, requested)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }
}

